text:
// Pawn Champ - Letters from Lisbon. Minor quest m38, batch H (docs/quests/MINOR.md#m38-letters-from-lisbon).
// A man clearing his late uncle's house sells you a bundle of love letters in Portuguese, never
// opened. The woman they're addressed to is ninety-one, and she meets the noon ferry every day.
// The uncle was the postmaster in 1958.
//
// Written as data: docs/STORY_DATA.md. Strict JSON inside the call. Code half: js/quests/lisbon.js.
defineStory({
  "id": "lisbon",
  "kind": "minor",
  "title": "Letters from Lisbon",
  "location": "ferry",
  "rumour": "Old Mrs. Soares has met the noon ferry every day since 1958. Nobody has ever got off it for her.",
  "endings": { "delivered": "Arrived", "sold": "Postal History", "kept": "Still Waiting" },
  "about": [
    "A quiet love story. Donny Rego, clearing out the house of his uncle Abel, the town postmaster until 1980, sells you a bundle of unopened letters from Lisbon he found under a false bottom in a desk (§{donnyLetters}). They're addressed to a Soares, and an old woman of that name sits on the bench at the ferry landing every day at noon.",
    "At the landing (§{lisbonLanding}) give Amélia Soares the letters, and she learns that Tomás, the Lisbon cod-boat sailor she waited for in 1957, did come back, and that Abel told him she'd married, then hid his letters and proposed to her every spring (Arrived). Or go back without saying anything. If you still have the letters, a stamp collector offers $140 for them (§{lisbonStamps}; Postal History); refuse after leaving her waiting and she keeps meeting the ferry (Still Waiting)."
  ],
  "cast": {
    "donny": {
      "name": "Donny Rego",
      "look": { "skin": "#c89870", "hair": "#2a2a2a", "hs": 0, "coat": "#4a4a5a", "style": "hoodie", "pants": "#3a3a42", "hat": "cap", "hatc": "#8a2a2a" }
    },
    "amelia": {
      "name": "Amélia Soares",
      "look": { "skin": "#c09070", "hair": "#f0f0f0", "hs": 1, "coat": "#2a3a5a", "trim": "#e8e4dc", "style": "dress", "long": true, "pants": "#2a2a3a", "bag": "#5a3a2a" }
    },
    "stampman": {
      "name": "Mr. Ordway, philatelist",
      "look": { "skin": "#f0d8c8", "hair": "#a8a8a8", "hs": 0, "coat": "#6a5a4a", "trim": "#c8a050", "style": "suit", "pants": "#4a3a2a", "glasses": "#2a2a2e", "bag": "#3a2a1e" }
    }
  },
  "uniques": {
    "lisbonLetters": {
      "name": "Letters from Lisbon",
      "icon": "letter",
      "cat": "curio",
      "guide": 30,
      "condLabel": "Never opened",
      "wantedBy": { "name": "Amélia Soares", "mult": 1 },
      "wantedKnown": "flag.lisbonKnown",
      "tells": [
        "Fourteen letters tied with a bootlace, Portuguese stamps, Lisbon postmarks from 1957 and 1958. Every one is sealed.",
        "All addressed in the same careful hand: Menina Amélia Soares, Hollow Neck, Massachusetts. The last is postmarked June 1958."
      ]
    }
  },
  "scenes": {
    "donnyLetters": {
      "title": "Donny Rego sells his uncle's letters",
      "customer": "donny",
      "steps": [
        {
          "say": "donny",
          "text": [
            "Donny Rego. I'm clearing out Uncle Abel's house. He was the postmaster here till 1980. He kept everything. I mean everything.",
            "These were in his desk, under a false bottom. Old Portuguese stamps. Somebody told me stamps are worth something."
          ]
        },
        { "offer": { "unique": "lisbonLetters" }, "persona": "honest", "asking": 30, "min": 20 },
        {
          "if": "offer == 'deal'",
          "then": [
            { "set": { "lisbonKnown": true } },
            { "say": "donny", "text": "Soares. Funny. There's an old lady called Soares who sits on the bench at the ferry landing. Every day. Noon. Rain or shine." },
            { "plan": "lisbon-landing" },
            { "toast": "Calendar: the noon ferry, at the town landing", "look": "donny" }
          ]
        },
        { "leave": "donny" }
      ]
    },
    "lisbonLanding": {
      "title": "The noon ferry",
      "steps": [
        {
          "stage": "ferryLandingNoon",
          "fadeOut": false,
          "actors": [
            { "id": "you", "cast": "keeper", "name": "You", "at": [110, 166] },
            {
              "id": "amelia",
              "cast": "amelia",
              "name": "An old woman on the bench",
              "at": [220, 164],
              "facingLeft": true
            }
          ]
        },
        { "narrate": "The town landing at noon. Gulls, the ticket hut, and on the bench by the gangway an old woman in a good blue coat with her handbag on her knees, watching the ferry come in." },
        { "find": "letters", "in": "stock", "match": { "uniqueId": "lisbonLetters" } },
        {
          "if": "!letters",
          "then": [
            { "narrate": "You came without the letters. She watches every passenger off, and then she watches the ferry leave again." },
            { "end": true }
          ]
        },
        { "say": "amelia", "text": "You're standing in front of my ferry, dear." },
        { "edit": "amelia", "set": { "name": "Amélia Soares" }, "note": "Now you know her name." },
        {
          "choose": [
            { "label": "Give her the letters" },
            {
              "label": "Say nothing, and go back to the shop",
              "then": [
                { "set": { "lisbonKept": true } },
                { "narrate": "She watches every passenger off, and then she watches the ferry leave. Then she goes home." },
                { "end": true }
              ]
            }
          ]
        },
        { "take": "letters" },
        { "refresh": "panel" },
        { "narrate": "She knows the handwriting before she has the bootlace off. She doesn't open them in order. She opens the last one first." },
        {
          "say": "amelia",
          "text": [
            "Tomás. He was a sailor on a cod boat out of Lisbon. 1957. He said he'd come back on the noon ferry, the first of June, and I was to be on the landing.",
            "\"I came. Abel at the post office told me you had married. I wish you every happiness. I will not write again.\" ...Abel. Abel Rego. He asked me to marry him every spring until he died."
          ]
        },
        { "narrate": "She laughs, and then she isn't laughing, and then she is again." },
        { "say": "amelia", "text": "Sixty-eight years on this bench. Well. I don't have to come tomorrow. I could go to Lisbon. Do you suppose they still have the noon ferry in Lisbon?" },
        { "rep": 4, "why": "Delivered the Lisbon letters" },
        { "set": { "lisbonEnd": "delivered" } }
      ]
    },
    "lisbonStamps": {
      "title": "A stamp collector wants the letters",
      "customer": "ordway",
      "steps": [
        { "find": "letters", "in": "stock", "match": { "uniqueId": "lisbonLetters" } },
        { "say": "ordway", "text": "Ordway. Philatelist. I heard a bundle of 1950s Portuguese covers turned up here, unopened. Unopened! Do you know how rare that is?" },
        {
          "choose": [
            {
              "label": "Sell him the letters",
              "hint": "(+$140)",
              "then": [
                { "sell": "letters", "to": "ordway" },
                { "refresh": "panel" },
                { "coin": 140, "why": "Sold the Lisbon letters to a stamp collector" },
                { "set": { "lisbonEnd": "sold" } },
                { "say": "ordway", "text": "I'll steam them very carefully. The stamps, I mean. The letters I'll just... file." }
              ]
            },
            {
              "label": "\"They're somebody's letters.\"",
              "then": [
                { "say": "ordway", "text": "Everything is somebody's, until it's a collection." },
                { "set": { "lisbonEnd": "kept" }, "if": "flag.lisbonKept" }
              ]
            }
          ]
        },
        { "leave": "ordway" }
      ]
    }
  },
  "beats": [
    { "at": "3-4", "cast": "donny", "scene": "donnyLetters" },
    { "at": "4-3", "cast": "stampman", "scene": "lisbonStamps", "if": "hook.lettersHere && !flag.lisbonEnd" }
  ],
  "errands": [
    {
      "id": "lisbon-landing",
      "title": "The noon ferry",
      "where": "the town landing",
      "scene": "lisbonLanding",
      "test": [{ "add": { "unique": "lisbonLetters" } }]
    }
  ],
  "calendar": [
    { "id": "lisbon-landing", "errand": "lisbon-landing", "story": "lisbon", "where": "The town landing", "title": "The noon ferry" }
  ],
  "epilogue": [
    { "line": "There is a postcard from Lisbon taped up in the ticket hut at the landing. It says: \"The ferry here is late too. A.\"", "if": "flag.lisbonEnd == 'delivered'" },
    { "line": "Amélia Soares still meets the noon ferry. You can see the bench from the shop, if you lean.", "if": "flag.lisbonEnd == 'kept'" }
  ],
  "talk": {
    "by": "skip",
    "rumour": [
      "Mrs. Soares's on the bench at the landing every day at noon. I wave from the bus. Sixty-odd years she's been meeting that ferry. Nobody ever gets off for her."
    ],
    "react": { "delivered": "Mrs. Soares wasn't on her bench today. Ticket hut says she bought one to Boston. Then on to somewhere with a lot of vowels.", "sold": "Some stamp man was showing off Portuguese envelopes at the diner. Mrs. Soares was on her bench. I didn't wave so much today.", "kept": "Mrs. Soares's on her bench. Noon, every day. I still wave." },
    "sway": { "delivered": { "skip": 2, "otis": 2 }, "kept": { "skip": 1 } }
  },
  "fallout": {
    "sold": { "id": "skip", "mood": "cold", "line": "Those were Mrs. Soares's letters. The stamp man showed everyone at the diner. I'm driving past your shop now, not stopping.", "after": "Skip Fairweather drove the long way round your block for the rest of the month." }
  },
  "outcome": "flag.lisbonEnd"
});
